machinefile: station.machinefile/v1
name: base-macos
description: A macOS workspace with Homebrew, git and zsh
machine:
    kind: workspace
    system: { os: macos, version: '26.6.2', arch: arm64 }
vm:
    lifetime: persistent
    resources: { cpus: 4, memory: 8G, disk: 80G }
    network: bridged
    image:
        {
            from: 'ghcr.io/cirruslabs/macos-tahoe-base@sha256:65c3133a633fda8753cf1f71f2d55727792d534a2125b0032466563dcc8e58fd',
        }
apps: [homebrew, git, ohmyzsh]
settings:
    git-shortcuts: {}
    hushlogin: {}

machinefile: station.machinefile/v1
name: base-ubuntu
description: A Linux workspace with the runtime manager, git, zsh, Docker and headless Chromium's libraries
machine:
    kind: workspace
    system: { os: ubuntu, version: '24.04', arch: arm64 }
vm:
    lifetime: ephemeral
    resources: { cpus: 4, memory: 8G, disk: 20G }
    network: nat
    image:
        {
            from: 'ghcr.io/cirruslabs/ubuntu:24.04',
            bake: [mise, git, docker, build-essential, playwright-deps],
        }
apps:
    - mise
    - { name: git, optional: true }
    - ohmyzsh
    - docker
    - build-essential
    - playwright-deps
settings:
    git-shortcuts: {}
    hushlogin: {}
